const items = $input.all();

const contexto = items.map(item => {
  const f = item.json.fields || {};

  return `
TEMA: ${f.Tema || ''}
PREGUNTA: ${f.Pregunta || ''}
RESPUESTA: ${f.Respuesta || ''}
CONTEXTO: ${f.Contexto || ''}
KEYWORDS: ${f.Keywords || ''}
`.trim();
}).join('\n\n---\n\n');

return [
  {
    json: {
      contextoRAG: `BASE DE CONOCIMIENTO OFICIAL\n\n${contexto}`
    }
  }
];
